# Let's try a simple greedy algorithm: repeatedly pick the vertex with smallest degree, add to independent set, remove it and its neighbors
import copy

def greedy_independent_set(adj_orig):
    adj = {k: set(v) for k, v in adj_orig.items()}
    selected = set()
    available = set(range(n))
    while available:
        # pick vertex with smallest degree among available
        v = min(available, key=lambda x: len(adj[x]))
        selected.add(v)
        # remove v and its neighbors
        to_remove = {v} | adj[v]
        for r in to_remove:
            if r in available:
                available.remove(r)
                for u in adj[r]:
                    if u in available:
                        adj[u].discard(r)
                adj[r].clear()
    return selected

ind_set = greedy_independent_set(adj)
print("Greedy independent set size:", len(ind_set))
print("Set:", sorted(ind_set))

